use std::cell::RefCell;
use std::collections::HashMap;
use std::io::{self, Read, Write};
use std::rc::Rc;

const LIMIT: i128 = 1_000_000_000_000_000;
const STEP_LIMIT: u64 = 200_000;
const MAX_DEPTH: usize = 100;
const RESERVED: [&str; 21] = [
    "define", "set!", "lambda", "let", "if", "begin", "while", "and", "or", "not", "print", "+", "*",
    "-", "/", "%", "<", ">", "<=", ">=", "=",
];

fn is_reserved(s: &str) -> bool {
    RESERVED.contains(&s)
}

// ---------- reading ----------

#[derive(Clone)]
enum Form {
    Int(i64, usize),
    Bool(bool, usize),
    Sym(String, usize),
    List(Vec<Form>, usize),
}

enum Tok {
    Open(usize),
    Close(usize),
    Atom(Form),
    Err(String, usize),
}

fn classify(s: &str, line: usize) -> Result<Form, String> {
    if s == "#t" {
        return Ok(Form::Bool(true, line));
    }
    if s == "#f" {
        return Ok(Form::Bool(false, line));
    }
    let digits = s.strip_prefix('-').unwrap_or(s);
    if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
        if digits.len() > 15 {
            return Err("number too large".to_string());
        }
        let v: i64 = s.parse().unwrap();
        return Ok(Form::Int(v, line));
    }
    Ok(Form::Sym(s.to_string(), line))
}

fn tokenize(src: &str) -> Vec<Tok> {
    let chars: Vec<char> = src.chars().collect();
    let mut toks = Vec::new();
    let mut line = 1;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\n' {
            line += 1;
            i += 1;
        } else if c.is_whitespace() {
            i += 1;
        } else if c == ';' {
            while i < chars.len() && chars[i] != '\n' {
                i += 1;
            }
        } else if c == '(' {
            toks.push(Tok::Open(line));
            i += 1;
        } else if c == ')' {
            toks.push(Tok::Close(line));
            i += 1;
        } else {
            let start = i;
            while i < chars.len() && !chars[i].is_whitespace() && !matches!(chars[i], '(' | ')' | ';') {
                i += 1;
            }
            let s: String = chars[start..i].iter().collect();
            match classify(&s, line) {
                Ok(f) => toks.push(Tok::Atom(f)),
                Err(msg) => {
                    toks.push(Tok::Err(msg, line));
                    return toks;
                }
            }
        }
    }
    toks
}

enum PErr {
    Unclosed,
    Msg(String, usize),
}

fn parse_list(toks: &[Tok], pos: &mut usize) -> Result<Vec<Form>, PErr> {
    let mut items = Vec::new();
    while *pos < toks.len() {
        match &toks[*pos] {
            Tok::Open(l) => {
                *pos += 1;
                let sub = parse_list(toks, pos)?;
                items.push(Form::List(sub, *l));
            }
            Tok::Close(_) => {
                *pos += 1;
                return Ok(items);
            }
            Tok::Atom(f) => {
                items.push(f.clone());
                *pos += 1;
            }
            Tok::Err(m, l) => return Err(PErr::Msg(m.clone(), *l)),
        }
    }
    Err(PErr::Unclosed)
}

fn parse_program(toks: &[Tok]) -> Result<Vec<Form>, (String, usize)> {
    let mut forms = Vec::new();
    let mut pos = 0;
    while pos < toks.len() {
        match &toks[pos] {
            Tok::Open(l) => {
                pos += 1;
                let items = parse_list(toks, &mut pos).map_err(|e| match e {
                    PErr::Unclosed => ("unclosed (".to_string(), *l),
                    PErr::Msg(m, ln) => (m, ln),
                })?;
                forms.push(Form::List(items, *l));
            }
            Tok::Close(l) => return Err(("unexpected )".to_string(), *l)),
            Tok::Atom(f) => {
                forms.push(f.clone());
                pos += 1;
            }
            Tok::Err(m, l) => return Err((m.clone(), *l)),
        }
    }
    Ok(forms)
}

// ---------- evaluation ----------

type EnvRef = Rc<RefCell<Env>>;

struct Env {
    vars: HashMap<String, Val>,
    parent: Option<EnvRef>,
}

struct Closure {
    params: Vec<String>,
    body: Rc<Vec<Form>>,
    env: EnvRef,
}

#[derive(Clone)]
enum Val {
    Int(i64),
    Bool(bool),
    Closure(Rc<Closure>),
}

struct RtErr {
    line: usize,
    msg: String,
}

fn rt<T>(line: usize, msg: impl Into<String>) -> Result<T, RtErr> {
    Err(RtErr { line, msg: msg.into() })
}

fn lookup(env: &EnvRef, name: &str) -> Option<Val> {
    let mut cur = env.clone();
    loop {
        let next = {
            let e = cur.borrow();
            if let Some(v) = e.vars.get(name) {
                return Some(v.clone());
            }
            e.parent.clone()
        };
        match next {
            Some(p) => cur = p,
            None => return None,
        }
    }
}

fn assign(env: &EnvRef, name: &str, val: &Val) -> Option<Val> {
    let mut cur = env.clone();
    loop {
        let next = {
            let mut e = cur.borrow_mut();
            if let Some(slot) = e.vars.get_mut(name) {
                let old = slot.clone();
                *slot = val.clone();
                return Some(old);
            }
            e.parent.clone()
        };
        match next {
            Some(p) => cur = p,
            None => return None,
        }
    }
}

fn show(v: &Val) -> String {
    match v {
        Val::Int(n) => n.to_string(),
        Val::Bool(true) => "#t".to_string(),
        Val::Bool(false) => "#f".to_string(),
        Val::Closure(_) => "<closure>".to_string(),
    }
}

fn want_bool(v: Val, line: usize) -> Result<bool, RtErr> {
    match v {
        Val::Bool(b) => Ok(b),
        _ => rt(line, "type error"),
    }
}

fn want_ints(vals: &[Val], line: usize) -> Result<Vec<i64>, RtErr> {
    let mut out = Vec::with_capacity(vals.len());
    for v in vals {
        match v {
            Val::Int(n) => out.push(*n),
            _ => return rt(line, "type error"),
        }
    }
    Ok(out)
}

fn check_range(v: i128, line: usize) -> Result<i128, RtErr> {
    if v.abs() > LIMIT {
        rt(line, "overflow")
    } else {
        Ok(v)
    }
}

struct Interp {
    steps: u64,
    depth: usize,
    out: String,
}

impl Interp {
    fn eval(&mut self, f: &Form, env: &EnvRef) -> Result<Val, RtErr> {
        match f {
            Form::Int(v, _) => Ok(Val::Int(*v)),
            Form::Bool(b, _) => Ok(Val::Bool(*b)),
            Form::Sym(name, line) => {
                lookup(env, name).ok_or_else(|| RtErr { line: *line, msg: format!("unbound variable {}", name) })
            }
            Form::List(items, line) => self.eval_list(items, *line, env),
        }
    }

    fn eval_all(&mut self, args: &[Form], env: &EnvRef) -> Result<Vec<Val>, RtErr> {
        let mut vals = Vec::with_capacity(args.len());
        for a in args {
            vals.push(self.eval(a, env)?);
        }
        Ok(vals)
    }

    fn eval_list(&mut self, items: &[Form], line: usize, env: &EnvRef) -> Result<Val, RtErr> {
        self.steps += 1;
        if self.steps > STEP_LIMIT {
            return rt(line, "step limit");
        }
        let head = match items.first() {
            Some(h) => h,
            None => return rt(line, "bad syntax"),
        };
        if let Form::Sym(name, _) = head {
            if is_reserved(name) {
                return self.special(name, items, line, env);
            }
        }
        self.call(items, line, env)
    }

    fn special(&mut self, name: &str, items: &[Form], line: usize, env: &EnvRef) -> Result<Val, RtErr> {
        let args = &items[1..];
        match name {
            "define" => {
                if args.len() != 2 {
                    return rt(line, "bad syntax");
                }
                let var = match &args[0] {
                    Form::Sym(n, _) if !is_reserved(n) => n.clone(),
                    _ => return rt(line, "bad syntax"),
                };
                let v = self.eval(&args[1], env)?;
                env.borrow_mut().vars.insert(var, v);
                Ok(Val::Int(0))
            }
            "set!" => {
                if args.len() != 2 {
                    return rt(line, "bad syntax");
                }
                let (var, vline) = match &args[0] {
                    Form::Sym(n, l) if !is_reserved(n) => (n.clone(), *l),
                    _ => return rt(line, "bad syntax"),
                };
                let v = self.eval(&args[1], env)?;
                match assign(env, &var, &v) {
                    Some(old) => Ok(old),
                    None => rt(vline, format!("unbound variable {}", var)),
                }
            }
            "lambda" => {
                if args.len() < 2 {
                    return rt(line, "bad syntax");
                }
                let params = match &args[0] {
                    Form::List(ps, _) => ps,
                    _ => return rt(line, "bad syntax"),
                };
                let mut names: Vec<String> = Vec::new();
                for p in params {
                    match p {
                        Form::Sym(n, _) if !is_reserved(n) && !names.contains(n) => names.push(n.clone()),
                        _ => return rt(line, "bad syntax"),
                    }
                }
                Ok(Val::Closure(Rc::new(Closure {
                    params: names,
                    body: Rc::new(args[1..].to_vec()),
                    env: env.clone(),
                })))
            }
            "let" => {
                if args.len() < 2 {
                    return rt(line, "bad syntax");
                }
                let binds = match &args[0] {
                    Form::List(b, _) => b,
                    _ => return rt(line, "bad syntax"),
                };
                let mut names: Vec<String> = Vec::new();
                let mut exprs: Vec<&Form> = Vec::new();
                for b in binds {
                    let pair = match b {
                        Form::List(p, _) if p.len() == 2 => p,
                        _ => return rt(line, "bad syntax"),
                    };
                    match &pair[0] {
                        Form::Sym(n, _) if !is_reserved(n) && !names.contains(n) => {
                            names.push(n.clone());
                            exprs.push(&pair[1]);
                        }
                        _ => return rt(line, "bad syntax"),
                    }
                }
                let vals = self.eval_all(&exprs.iter().map(|e| (*e).clone()).collect::<Vec<Form>>(), env)?;
                let child = Rc::new(RefCell::new(Env {
                    vars: names.into_iter().zip(vals).collect(),
                    parent: Some(env.clone()),
                }));
                let mut last = Val::Int(0);
                for f in &args[1..] {
                    last = self.eval(f, &child)?;
                }
                Ok(last)
            }
            "if" => {
                if args.len() < 2 || args.len() > 3 {
                    return rt(line, "bad syntax");
                }
                let c = self.eval(&args[0], env)?;
                if want_bool(c, line)? {
                    self.eval(&args[1], env)
                } else if args.len() == 3 {
                    self.eval(&args[2], env)
                } else {
                    Ok(Val::Int(0))
                }
            }
            "begin" => {
                let mut last = Val::Int(0);
                for f in args {
                    last = self.eval(f, env)?;
                }
                Ok(last)
            }
            "while" => {
                if args.len() < 2 {
                    return rt(line, "bad syntax");
                }
                loop {
                    let c = self.eval(&args[0], env)?;
                    if !want_bool(c, line)? {
                        break;
                    }
                    for f in &args[1..] {
                        self.eval(f, env)?;
                    }
                }
                Ok(Val::Int(0))
            }
            "and" => {
                for f in args {
                    let v = self.eval(f, env)?;
                    if !want_bool(v, line)? {
                        return Ok(Val::Bool(false));
                    }
                }
                Ok(Val::Bool(true))
            }
            "or" => {
                for f in args {
                    let v = self.eval(f, env)?;
                    if want_bool(v, line)? {
                        return Ok(Val::Bool(true));
                    }
                }
                Ok(Val::Bool(false))
            }
            "not" => {
                if args.len() != 1 {
                    return rt(line, "bad syntax");
                }
                let v = self.eval(&args[0], env)?;
                Ok(Val::Bool(!want_bool(v, line)?))
            }
            "print" => {
                if args.len() != 1 {
                    return rt(line, "bad syntax");
                }
                let v = self.eval(&args[0], env)?;
                self.out.push_str(&show(&v));
                self.out.push('\n');
                Ok(Val::Int(0))
            }
            "+" | "*" => {
                let vals = self.eval_all(args, env)?;
                let ints = want_ints(&vals, line)?;
                let plus = name == "+";
                let mut acc: i128 = if plus { 0 } else { 1 };
                for n in ints {
                    acc = check_range(if plus { acc + n as i128 } else { acc * n as i128 }, line)?;
                }
                Ok(Val::Int(acc as i64))
            }
            "-" => {
                if args.is_empty() {
                    return rt(line, "bad syntax");
                }
                let vals = self.eval_all(args, env)?;
                let ints = want_ints(&vals, line)?;
                if ints.len() == 1 {
                    return Ok(Val::Int(-ints[0]));
                }
                let mut acc = ints[0] as i128;
                for n in &ints[1..] {
                    acc = check_range(acc - *n as i128, line)?;
                }
                Ok(Val::Int(acc as i64))
            }
            "/" | "%" => {
                if args.len() != 2 {
                    return rt(line, "bad syntax");
                }
                let vals = self.eval_all(args, env)?;
                let ints = want_ints(&vals, line)?;
                let (a, b) = (ints[0], ints[1]);
                if b == 0 {
                    return rt(line, "division by zero");
                }
                Ok(Val::Int(if name == "/" { a / b } else { a % b }))
            }
            _ => {
                // comparison operators
                if args.len() != 2 {
                    return rt(line, "bad syntax");
                }
                let vals = self.eval_all(args, env)?;
                let ints = want_ints(&vals, line)?;
                let (a, b) = (ints[0], ints[1]);
                let r = match name {
                    "<" => a < b,
                    ">" => a > b,
                    "<=" => a <= b,
                    ">=" => a >= b,
                    _ => a == b,
                };
                Ok(Val::Bool(r))
            }
        }
    }

    fn call(&mut self, items: &[Form], line: usize, env: &EnvRef) -> Result<Val, RtErr> {
        let clo = match self.eval(&items[0], env)? {
            Val::Closure(c) => c,
            _ => return rt(line, "not a function"),
        };
        let argv = self.eval_all(&items[1..], env)?;
        if argv.len() != clo.params.len() {
            return rt(line, "wrong number of arguments");
        }
        if self.depth >= MAX_DEPTH {
            return rt(line, "stack overflow");
        }
        let child = Rc::new(RefCell::new(Env {
            vars: clo.params.iter().cloned().zip(argv).collect(),
            parent: Some(clo.env.clone()),
        }));
        self.depth += 1;
        let mut last = Val::Int(0);
        for f in clo.body.iter() {
            last = self.eval(f, &child)?;
        }
        self.depth -= 1;
        Ok(last)
    }
}

fn run() -> i32 {
    let mut src = String::new();
    if io::stdin().read_to_string(&mut src).is_err() {
        return 2;
    }
    let toks = tokenize(&src);
    let forms = match parse_program(&toks) {
        Ok(f) => f,
        Err((msg, line)) => {
            println!("parse error line {}: {}", line, msg);
            return 2;
        }
    };
    let global: EnvRef = Rc::new(RefCell::new(Env {
        vars: HashMap::new(),
        parent: None,
    }));
    let mut it = Interp {
        steps: 0,
        depth: 0,
        out: String::new(),
    };
    for f in &forms {
        if let Err(e) = it.eval(f, &global) {
            print!("{}", it.out);
            println!("error line {}: {}", e.line, e.msg);
            return 1;
        }
    }
    print!("{}", it.out);
    0
}

fn main() {
    let handle = std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(run)
        .unwrap();
    let code = handle.join().unwrap_or(1);
    io::stdout().flush().ok();
    std::process::exit(code);
}
